`timescale 1ns/1ps
module tb_mlkem_noise_sampler;reg clk=0,rst_n=0,start=0,ordy=1,was_stalled=0;reg[255:0]seed;reg[7:0]nonce;reg[1:0]eta;wire busy,done,error,ov;wire[11:0]oc;wire[7:0]oi;wire[1:0]dom;integer fd,rc,v,i,got,checks=0,cycles,totalcycles=0,stallcycle=0;reg[11:0]exp[0:255],held_c;reg[7:0]held_i;string file;always#5 clk=~clk;mlkem_noise_sampler dut(clk,rst_n,start,seed,nonce,eta,busy,done,error,ov,ordy,oc,oi,dom);
 initial begin if(!$value$plusargs("VECTOR_FILE=%s",file))$fatal(1,"VECTOR_FILE");fd=$fopen(file,"r");repeat(3)@(negedge clk);rst_n=1;for(v=0;v<128;v=v+1)begin rc=$fscanf(fd,"%d %h %h\n",eta,nonce,seed);for(i=0;i<256;i=i+1)rc=$fscanf(fd,"%h\n",exp[i]);@(negedge clk);start=1;@(negedge clk);start=0;got=0;cycles=0;while(!done)begin @(negedge clk);cycles=cycles+1;if(cycles>2500)$fatal(1,"watchdog v=%0d",v);end totalcycles=totalcycles+cycles;if(error||got!=256)$fatal(1,"status v=%0d",v);end
  @(negedge clk);start=1;@(negedge clk);start=0;got=0;repeat(90)@(negedge clk);rst_n=0;@(negedge clk);if(busy||done||ov)$fatal(1,"reset cancel");rst_n=1;@(negedge clk);start=1;@(negedge clk);start=0;got=0;while(!done)@(negedge clk);if(error||got!=256)$fatal(1,"restart");
  $display("PASS tb_mlkem_noise_sampler vectors=128 eta2=64 eta3=64 coeff_checks=%0d average_cycles=%0d reset_restart=PASS backpressure=PASS",checks,totalcycles/128);$finish;end
 always@(negedge clk)if(rst_n)begin stallcycle=stallcycle+1;ordy=(stallcycle%7)!=3;end
 always@(posedge clk)begin if(!rst_n)was_stalled=0;else begin if(was_stalled&&(!ov||oc!==held_c||oi!==held_i))$fatal(1,"stalled output changed");was_stalled=ov&&!ordy;if(ov&&!ordy)begin held_c=oc;held_i=oi;end if(ov&&ordy)begin if(got>=256||oi!==got[7:0]||oc!==exp[got]||dom!=2'b01)$fatal(1,"v=%0d i=%0d exp=%0d got=%0d child_count=%0d child_valid=%b child_busy=%b parent_done=%b",v,got,exp[got],oc,dut.c.coeff_count,dut.c.out_valid,dut.c.busy,done);got=got+1;checks=checks+1;end end end endmodule
